int load_tss_state(struct x86_emulate_ctxt *ctxt, struct tss_segment_32 *tss) {
    int rc;

    /* Load CR3 */
    ctxt->cr[3] = tss->cr3;

    /* Set instruction pointer and flags */
    ctxt->eip = tss->eip;
    ctxt->eflags = tss->eflags;

    /* Load general-purpose registers */
    ctxt->regs[VCPU_REGS_RAX] = tss->eax;
    ctxt->regs[VCPU_REGS_RCX] = tss->ecx;
    ctxt->regs[VCPU_REGS_RDX] = tss->edx;
    ctxt->regs[VCPU_REGS_RBX] = tss->ebx;
    ctxt->regs[VCPU_REGS_RSP] = tss->esp;
    ctxt->regs[VCPU_REGS_RBP] = tss->ebp;
    ctxt->regs[VCPU_REGS_RSI] = tss->esi;
    ctxt->regs[VCPU_REGS_RDI] = tss->edi;

    /* Load segment selectors first */
    ctxt->regs[VCPU_REGS_SS] = tss->ss0;
    ctxt->regs[VCPU_REGS_CS] = tss->cs;
    ctxt->regs[VCPU_REGS_DS] = tss->ds;
    ctxt->regs[VCPU_REGS_ES] = tss->es;
    ctxt->regs[VCPU_REGS_FS] = tss->fs;
    ctxt->regs[VCPU_REGS_GS] = tss->gs;

    /* Load segment descriptors and handle mode switch logic */
    if ((rc = load_segment_descriptor(ctxt, tss->cs, SEGMENT_CS, tss->cs_base, tss->cs_limit, tss->cs_ar)) != X86EMUL_CONTINUE)
        return rc;
    if ((rc = load_segment_descriptor(ctxt, tss->ss, SEGMENT_SS, tss->ss_base, tss->ss_limit, tss->ss_ar)) != X86EMUL_CONTINUE)
        return rc;
    if ((rc = load_segment_descriptor(ctxt, tss->ds, SEGMENT_DS, tss->ds_base, tss->ds_limit, tss->ds_ar)) != X86EMUL_CONTINUE)
        return rc;
    if ((rc = load_segment_descriptor(ctxt, tss->es, SEGMENT_ES, tss->es_base, tss->es_limit, tss->es_ar)) != X86EMUL_CONTINUE)
        return rc;
    if ((rc = load_segment_descriptor(ctxt, tss->fs, SEGMENT_FS, tss->fs_base, tss->fs_limit, tss->fs_ar)) != X86EMUL_CONTINUE)
        return rc;
    if ((rc = load_segment_descriptor(ctxt, tss->gs, SEGMENT_GS, tss->gs_base, tss->gs_limit, tss->gs_ar)) != X86EMUL_CONTINUE)
        return rc;

    /* If LDT is used, load it */
    if (tss->ldt != 0) {
        if ((rc = load_segment_descriptor(ctxt, tss->ldt, SEGMENT_LDT, tss->ldt_base, tss->ldt_limit, tss->ldt_ar)) != X86EMUL_CONTINUE)
            return rc;
    }

    return X86EMUL_CONTINUE;
}

